const express = require('express');
const { param, query, validationResult } = require('express-validator');
const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, QueryCommand, GetCommand } = require('@aws-sdk/lib-dynamodb');

const app = express();
const ddbDoc = DynamoDBDocumentClient.from(new DynamoDBClient({ region: 'us-east-1' }));

const tripsValidation = [
  param('vin').matches(/^[A-HJ-NPR-Z0-9]{17}$/).withMessage('Valid 17-character VIN required'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
];

app.get('/api/fleet/vehicles/:vin/trips', tripsValidation, async (req, res) => {
  if (!req.user || !req.user.carrierId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { vin } = req.params;
  const limit = parseInt(req.query.limit, 10) || 20;

  // Verify carrier owns or operates this vehicle
  const vehicleCheck = await ddbDoc.send(new GetCommand({
    TableName: 'RegisteredVehicles',
    Key: { vin }
  }));

  if (!vehicleCheck.Item || vehicleCheck.Item.carrierId !== req.user.carrierId) {
    return res.status(403).json({ error: 'Forbidden: vehicle not assigned to your carrier' });
  }

  const cmd = new QueryCommand({
    TableName: 'FleetTrips',
    KeyConditionExpression: 'vin = :vin',
    ExpressionAttributeValues: { ':vin': vin },
    Limit: limit,
    ScanIndexForward: false
  });

  const result = await ddbDoc.send(cmd);
  res.json({ vin, count: result.Items.length, trips: result.Items });
});

app.listen(6005);
